example:
# main.tf written in HCL
resource "aws_s3_bucket" "logs" {
  bucket = "acme-logs"   # argument = value syntax
}

# You declare the end state; Terraform works out the create/update/delete calls
resource "aws_instance" "web" {
  ami           = "ami-0abc123"
  instance_type = "t3.micro"
}
# terraform plan shows: 1 to add, 0 to change, 0 to destroy

provider "aws" {
  region  = "ap-southeast-1"
  profile = "prod"   # credentials profile used for API calls
}

resource "aws_instance" "web" {
  ami           = "ami-0abc123"
  instance_type = "t3.micro"
}
# referenced elsewhere as aws_instance.web.id

data "aws_ami" "ubuntu" {
  most_recent = true
  owners      = ["099720109477"]   # Canonical
  filter {
    name   = "name"
    values = ["ubuntu/images/*22.04*"]
  }
}
# use: ami = data.aws_ami.ubuntu.id

variable "instance_type" {
  type        = string
  default     = "t3.micro"
  description = "EC2 size for the web tier"
}
# override: terraform apply -var="instance_type=t3.small"

output "web_public_ip" {
  value       = aws_instance.web.public_ip
  description = "Address of the web server"
}
# terraform output web_public_ip  -> 54.12.34.56

locals {
  name_prefix = "${var.project}-${terraform.workspace}"
  common_tags = { Project = var.project, Env = terraform.workspace }
}
# use: tags = local.common_tags

terraform state show aws_instance.web
# resource "aws_instance" "web" {
#   id            = "i-0abc123def456"   # real-world object ID
#   instance_type = "t3.micro"
# }

terraform {
  backend "s3" {
    bucket         = "acme-tfstate"
    key            = "prod/network.tfstate"
    region         = "ap-southeast-1"
    use_lockfile   = true   # S3-native locking (Terraform 1.10+)
  }
}

terraform state rm aws_instance.legacy
# Removed aws_instance.legacy
# The EC2 instance keeps running; Terraform just forgets it.
# Terraform 1.7+ alternative:
removed {
  from = aws_instance.legacy
  lifecycle { destroy = false }
}

terraform workspace select staging
resource "aws_s3_bucket" "data" {
  bucket = "acme-data-${terraform.workspace}"   # acme-data-staging
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"   # public registry address
  version = "~> 5.0"
  name    = "prod"
}
module "app" {
  source = "./modules/app"   # local path
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 3.0"   # allows 3.0.0, 3.14.4, ... but not 4.0.0
}

resource "aws_db_instance" "main" {
  # ...
  lifecycle {
    prevent_destroy       = true
    create_before_destroy = true
    ignore_changes        = [tags["LastScanned"]]
  }
}

resource "aws_launch_template" "web" {
  # ...
  lifecycle {
    create_before_destroy = true   # new template exists before old one is removed
  }
}

resource "aws_db_instance" "prod" {
  # ...
  lifecycle { prevent_destroy = true }
}
# terraform destroy
# Error: Instance cannot be destroyed
#   Resource aws_db_instance.prod has lifecycle.prevent_destroy set

resource "aws_autoscaling_group" "web" {
  desired_capacity = 2
  # ...
  lifecycle {
    ignore_changes = [desired_capacity]   # autoscaler adjusts this outside Terraform
  }
}

variable "buckets" {
  default = { logs = "private", assets = "public-read" }
}
resource "aws_s3_bucket" "b" {
  for_each = var.buckets
  bucket   = "acme-${each.key}"   # addresses: aws_s3_bucket.b["logs"], ["assets"]
}

resource "aws_subnet" "private" {
  count      = 3
  cidr_block = cidrsubnet(var.vpc_cidr, 8, count.index)   # 0, 1, 2
  tags       = { Name = "private-${count.index}" }
}

variable "users" {
  default = { alice = "admin", bob = "viewer" }
}
resource "aws_iam_user" "u" {
  for_each = var.users
  name     = each.key            # alice, bob
  tags     = { role = each.value }   # admin, viewer
}

resource "aws_instance" "web" {
  count    = 2
  for_each = toset(["a", "b"])   # invalid
}
# Error: Invalid combination of "count" and "for_each"

resource "aws_iam_role_policy" "s3_access" { ... }
resource "aws_instance" "app" {
  # no expression references the policy, but the app needs it at boot
  depends_on = [aws_iam_role_policy.s3_access]
}

resource "aws_instance" "web" {
  # ...
  provisioner "local-exec" {
    command = "echo ${self.private_ip} >> inventory.txt"   # runs on the Terraform host
  }
}

# Preferred: built-in provider feature instead of a provisioner
resource "aws_instance" "web" {
  ami       = data.aws_ami.ubuntu.id
  user_data = file("${path.module}/cloud-init.yaml")   # cloud-init handles bootstrap
}

provisioner "remote-exec" {
  inline = ["sudo apt-get install -y nginx"]
  connection { type = "ssh", host = self.public_ip, user = "ubuntu" }
}
# If SSH fails during apply, the resource is created but marked tainted

# main.tf must already contain: resource "aws_s3_bucket" "logs" {}
terraform import aws_s3_bucket.logs acme-logs
# Import successful!  (state updated; you still write the HCL yourself)

# imports.tf
import {
  to = aws_s3_bucket.logs
  id = "acme-logs"
}
terraform plan -generate-config-out=generated.tf   # writes HCL for the bucket

variable "db_password" {
  type      = string
  sensitive = true
}
# terraform plan
#   + password = (sensitive value)

output "db_endpoint" {
  # endpoint is derived from a sensitive value but is safe to display
  value = nonsensitive(aws_db_instance.main.endpoint)
}

terraform {
  required_version = ">= 1.5.0, < 2.0.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.40"   # 5.40.x through 5.x, not 6.0
    }
  }
}

cat .terraform.lock.hcl
# provider "registry.terraform.io/hashicorp/aws" {
#   version     = "5.60.0"
#   constraints = "~> 5.40"
#   hashes      = ["h1:...", "zh:..."]
# }

# Instead of ssh-ing in to patch, bake a new image and roll it out
packer build web.pkr.hcl                       # produces ami-0new
resource "aws_launch_template" "web" {
  image_id = "ami-0new"   # ASG replaces old instances with fresh ones
}

